def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    # If n is less than 8, it cannot be written as the sum of exactly 4 positive even numbers
    if n < 8:
        return False

    # Check if n can be written as the sum of 4 even numbers
    # Since all even numbers are multiples of 2, n must be at least 8 and divisible by 2
    if n % 2 != 0:
        return False

    # Start from the smallest possible sum of 4 even numbers, which is 8 (2+2+2+2)
    for i in range(8, n, 2):
        for j in range(i, n, 2):
            for k in range(j, n, 2):
                for l in range(k, n, 2):
                    if i + j + k + l == n:
                        return True

    return False

