def do_algebra(operator, operand):
    import operator as op  # Importing Python's built-in operator module

    if len(operator) != len(operand) - 1:
        raise ValueError("The length of the operator list must be one less than the operand list.")

    if not all(isinstance(x, int) and x >= 0 for x in operand):
        raise ValueError("All elements in the operand list must be non-negative integers.")

    expression = operand[0]

    for i in range(len(operator)):
        if operator[i] == '+':
            expression += operand[i + 1]
        elif operator[i] == '-':
            expression -= operand[i + 1]
        elif operator[i] == '*':
            expression *= operand[i + 1]
        elif operator[i] == '//':
            expression //= operand[i + 1]
        elif operator[i] == '**':
            expression **= operand[i + 1]
        else:
            raise ValueError(f"Unsupported operator: {operator[i]}")

    return expression
```

